    public static func divide<U, V>(_ scalar: Float, _ vector: U, result: inout V) where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Float, V.Element == Float {
        let n = Swift.min(vector.count, result.count); guard n > 0 else { return }
        var s = scalar
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { r in vDSP_svdiv(&s, a.baseAddress, 1, r.baseAddress, 1, vDSP_Length(n)) } }
    }
