    /// (the index of the first largest element, its value)
    public static func indexOfMaximum<U>(_ vector: U) -> (UInt, Float) where U: AccelerateBuffer, U.Element == Float {
        var v: Float = 0, i: vDSP_Length = 0
        vector.withUnsafeBufferPointer { a in vDSP_maxvi(a.baseAddress, 1, &v, &i, vDSP_Length(a.count)) }
        return (i, v)
    }
    public static func indexOfMinimum<U>(_ vector: U) -> (UInt, Float) where U: AccelerateBuffer, U.Element == Float {
        var v: Float = 0, i: vDSP_Length = 0
        vector.withUnsafeBufferPointer { a in vDSP_minvi(a.baseAddress, 1, &v, &i, vDSP_Length(a.count)) }
        return (i, v)
    }
    public static func clip<U>(_ vector: U, to bounds: ClosedRange<Float>) -> [Float] where U: AccelerateBuffer, U.Element == Float {
        _array(vector.count) { clip(vector, to: bounds, result: &$0) }
    }
    public static func clip<U, V>(_ vector: U, to bounds: ClosedRange<Float>, result: inout V) where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Float, V.Element == Float {
        let n = Swift.min(vector.count, result.count); guard n > 0 else { return }
        var lo = bounds.lowerBound, hi = bounds.upperBound
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { r in vDSP_vclip(a.baseAddress, 1, &lo, &hi, r.baseAddress, 1, vDSP_Length(n)) } }
    }
    public static func fill<V>(_ vector: inout V, with value: Float) where V: AccelerateMutableBuffer, V.Element == Float {
        var s = value
        vector.withUnsafeMutableBufferPointer { r in if r.count > 0 { vDSP_vfill(&s, r.baseAddress, 1, vDSP_Length(r.count)) } }
    }
    public static func clear<V>(_ vector: inout V) where V: AccelerateMutableBuffer, V.Element == Float {
        vector.withUnsafeMutableBufferPointer { r in if r.count > 0 { vDSP_vclr(r.baseAddress, 1, vDSP_Length(r.count)) } }
    }
    public static func ramp(withInitialValue initialValue: Float, increment: Float, count: Int) -> [Float] {
        _array(count) { r in var a = initialValue, b = increment; if count > 0 { vDSP_vramp(&a, &b, r.baseAddress, 1, vDSP_Length(count)) } }
    }
    public static func ramp(in range: ClosedRange<Float>, count: Int) -> [Float] {
        _array(count) { r in var a = range.lowerBound, b = range.upperBound; if count > 0 { vDSP_vgen(&a, &b, r.baseAddress, 1, vDSP_Length(count)) } }
    }
    public static func reverse<V>(_ vector: inout V) where V: AccelerateMutableBuffer, V.Element == Float {
        vector.withUnsafeMutableBufferPointer { r in if r.count > 0 { vDSP_vrvrs(r.baseAddress, 1, vDSP_Length(r.count)) } }
    }
    public static func sort<V>(_ vector: inout V, sortOrder: vDSP.SortOrder) where V: AccelerateMutableBuffer, V.Element == Float {
        vector.withUnsafeMutableBufferPointer { r in if r.count > 0 { vDSP_vsort(r.baseAddress, vDSP_Length(r.count), sortOrder.rawValue) } }
    }
    public static func linearInterpolate<T, U>(_ vectorA: T, _ vectorB: U, using interpolationConstant: Float) -> [Float] where T: AccelerateBuffer, U: AccelerateBuffer, T.Element == Float, U.Element == Float {
        _array(Swift.min(vectorA.count, vectorB.count)) { linearInterpolate(vectorA, vectorB, using: interpolationConstant, result: &$0) }
    }
    public static func linearInterpolate<T, U, V>(_ vectorA: T, _ vectorB: U, using interpolationConstant: Float, result: inout V) where T: AccelerateBuffer, U: AccelerateBuffer, V: AccelerateMutableBuffer, T.Element == Float, U.Element == Float, V.Element == Float {
        let n = Swift.min(vectorA.count, vectorB.count, result.count); guard n > 0 else { return }
        var c = interpolationConstant
        vectorA.withUnsafeBufferPointer { a in vectorB.withUnsafeBufferPointer { b in result.withUnsafeMutableBufferPointer { r in
            vDSP_vintb(a.baseAddress, 1, b.baseAddress, 1, &c, r.baseAddress, 1, vDSP_Length(n)) } } }
    }
    /// vector.count - kernel.count results: result[n] = sum_k vector[n + k] kernel[kernel.count - 1 - k]
    public static func convolve<T, U>(_ vector: T, withKernel kernel: U) -> [Float] where T: AccelerateBuffer, U: AccelerateBuffer, T.Element == Float, U.Element == Float {
        _array(Swift.max(0, vector.count - kernel.count)) { convolve(vector, withKernel: kernel, result: &$0) }
    }
    public static func convolve<T, U, V>(_ vector: T, withKernel kernel: U, result: inout V) where T: AccelerateBuffer, U: AccelerateBuffer, V: AccelerateMutableBuffer, T.Element == Float, U.Element == Float, V.Element == Float {
        _conv(vector, kernel, &result, reversed: true, vDSP_conv)
    }
    /// vector.count - kernel.count results: result[n] = sum_k vector[n + k] kernel[k]
    public static func correlate<T, U>(_ vector: T, withKernel kernel: U) -> [Float] where T: AccelerateBuffer, U: AccelerateBuffer, T.Element == Float, U.Element == Float {
        _array(Swift.max(0, vector.count - kernel.count)) { correlate(vector, withKernel: kernel, result: &$0) }
    }
    public static func correlate<T, U, V>(_ vector: T, withKernel kernel: U, result: inout V) where T: AccelerateBuffer, U: AccelerateBuffer, V: AccelerateMutableBuffer, T.Element == Float, U.Element == Float, V.Element == Float {
        _conv(vector, kernel, &result, reversed: false, vDSP_conv)
    }
